5	/**
6	 * Runs async jobs with a concurrency limit, priorities, retries and a queue ttl.
7	 *   now()              clock in ms
8	 *   schedule(fn, ms)   timer injected by the caller (used for retry delays)
9	 *   ttl                max time a job may wait since submit before it starts; waiting exactly ttl is still fine
10	 * submit() resolves to { name, status: 'done' | 'failed' | 'expired', attempts, value | error }.
11	 */
12	export class Runner {
13	  #queue = new PriorityQueue();
14	  #active = 0;
15	
16	  constructor({ now, schedule, concurrency = 2, maxAttempts = 3, ttl = '1m', backoff = {} }) {
17	    this.now = now;
18	    this.schedule = schedule;
19	    this.concurrency = concurrency;
20	    this.maxAttempts = maxAttempts;
21	    this.ttl = parseDuration(ttl);
22	    this.backoff = { ...backoff };
23	    if (backoff.base !== undefined) this.backoff.base = parseDuration(backoff.base);
24	    if (backoff.max !== undefined) this.backoff.max = parseDuration(backoff.max);
25	  }
26	
27	  submit(name, fn, { priority = 0 } = {}) {
28	    return new Promise((resolve) => {
29	      const job = { name, fn, priority, attempts: 0, enqueuedAt: this.now(), resolve };
30	      this.#queue.push(job, priority);
31	      this.#pump();
32	    });
33	  }
34	
35	  #pump() {
36	    while (this.#active < this.concurrency && this.#queue.size > 0) {
37	      const job = this.#queue.pop();
38	      if (this.now() - job.enqueuedAt >= this.ttl) {
39	        job.resolve({ name: job.name, status: 'expired', attempts: job.attempts });
40	        continue;
41	      }
42	      this.#active++;
43	      this.#run(job);
44	    }
45	  }
46	
47	  async #run(job) {
48	    job.attempts++;
49	    try {
50	      const value = await job.fn(job.attempts);
51	      job.resolve({ name: job.name, status: 'done', attempts: job.attempts, value });
52	    } catch (error) {
53	      if (job.attempts < this.maxAttempts) {
54	        const delay = backoffDelay(job.attempts, this.backoff);
55	        this.schedule(() => {
56	          this.#queue.push(job, job.priority);
57	          this.#pump();
58	        }, delay);
59	      } else {
60	        job.resolve({ name: job.name, status: 'failed', attempts: job.attempts, error });
61	      }
62	    } finally {
63	      this.#active--;
64	      this.#pump();
65	    }
66	  }
67	}

