2	export class PriorityQueue {
3	  #heap = [];
4	  #seq = 0;
5	
6	  get size() {
7	    return this.#heap.length;
8	  }
9	
10	  push(item, priority = 0) {
11	    const h = this.#heap;
12	    h.push({ item, priority, seq: this.#seq++ });
13	    let i = h.length - 1;
14	    while (i > 0) {
15	      const p = (i - 1) >> 1;
16	      if (!this.#before(h[i], h[p])) break;
17	      [h[i], h[p]] = [h[p], h[i]];
18	      i = p;
19	    }
20	  }
21	
22	  pop() {
23	    const h = this.#heap;
24	    if (h.length === 0) return undefined;
25	    const top = h[0];
26	    const last = h.pop();
27	    if (h.length > 0) {
28	      h[0] = last;
29	      let i = 0;
30	      for (;;) {
31	        const l = 2 * i + 1, r = l + 1;
32	        let best = i;
33	        if (l < h.length && this.#before(h[l], h[best])) best = l;
34	        if (r < h.length && this.#before(h[r], h[best])) best = r;
35	        if (best === i) break;
36	        [h[i], h[best]] = [h[best], h[i]];
37	        i = best;
38	      }
